113	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
114	    @Override
115	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
116	        Collection<Owner> owners;
117	        if (lastName != null) {
