142	    /**
143	     * Validates and normalizes the submitted owner fields, builds the owner, enforces the create-time
144	     * duplicate rules and persists it, returning the saved owner. This holds the whole "make and store
145	     * a new owner" flow in one place, separate from turning that owner into an HTTP response
146	     * ({@link #ownerResponse(Owner, HttpStatus)}), so the create endpoint reads as "create the owner,
147	     * then respond" and the persisted owner is available to callers that need it beyond the response.
148	     *
149	     * @param ownerFieldsDto the submitted owner fields, normalized in place as part of the create
150	     * @return the persisted owner, with its derived fields populated
151	     */
152	    private Owner createOwner(OwnerFieldsDto ownerFieldsDto) {
153	        normalizeAddress(ownerFieldsDto);
154	        rejectBlankOwnerFields(ownerFieldsDto);
155	        rejectDisposableEmailDomain(ownerFieldsDto.getEmail());
156	        boolean sharesHousehold = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
157	        rejectInvalidPostcode(ownerFieldsDto.getCity(), ownerFieldsDto.getPostcode());
158	        rejectCityAtCapacity(ownerFieldsDto.getCity());
159	        rejectFutureRegistrationDate(ownerFieldsDto.getRegistrationDate());
160	        LocalDate registrationDate = businessDay(effectiveRegistrationDate(ownerFieldsDto.getRegistrationDate()));
161	        rejectDailyRegistrationLimit(registrationDate);
162	        String normalizedTelephone = telephoneNormalizer.normalize(ownerFieldsDto.getTelephone());
163	        ownerFieldsDto.setTelephone(normalizedTelephone);
164	        String normalizedEmail = emailNormalizer.normalize(ownerFieldsDto.getEmail());
165	        ownerFieldsDto.setEmail(normalizedEmail);
166	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
167	        owner.setRegistrationDate(registrationDate);
168	        owner.setCustomerCode(customerCode(owner));
169	        owner.setNamesakeCount(namesakeCount(owner.getFirstName(), owner.getLastName()));
170	        owner.setHouseholdId(householdId(owner));
171	        rejectDuplicateIdentity(owner);
172	        rejectHouseholdDuplicate(owner, sharesHousehold);
173	        owner.setPossibleDuplicateOf(sharesHousehold ? null : possibleDuplicateOf(owner));
174	        this.clinicService.saveOwner(owner);
175	        owner.setHouseholdSize(householdSize(owner));
176	        AUDIT.info("Owner created: id={} customerCode={} registrationDate={} membershipLevel={} membershipNumber={}",
177	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(),
178	            ownerMapper.membershipLevel(owner), ownerMapper.membershipNumber(owner));
179	        return owner;
180	    }
