183	     * Builds the response for an owner: its derived-field DTO (see
184	     * {@link #toOwnerDtoWithDerivedFields(Owner)}) as the body and a {@code Location} header pointing at
185	     * the owner's canonical URL, returned with the given {@code status}. Assembling the response in one
186	     * place keeps "what to return for an owner" separate from the create flow that produced it, so any
187	     * path that returns an owner does so identically (differing only in the status it carries).
188	     *
189	     * @param owner the persisted owner to represent
190	     * @param status the HTTP status to return
191	     * @return the owner response with its body, {@code Location} header and status
192	     */
193	    private ResponseEntity<OwnerDto> ownerResponse(Owner owner, HttpStatus status) {
194	        OwnerDto ownerDto = toOwnerDtoWithDerivedFields(owner);
195	        HttpHeaders headers = new HttpHeaders();
196	        headers.setLocation(UriComponentsBuilder.newInstance()
197	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
198	        return new ResponseEntity<>(ownerDto, headers, status);
199	    }
