289	
290	    /**
291	     * Loads the owner with the given id and, when it exists, produces the response through
292	     * {@code action}; when no such owner exists a {@code 404 Not Found} is returned instead. The
293	     * single-owner endpoints share this "find the owner or report 404" preamble, so the lookup and
294	     * the not-found response are written in exactly one place rather than copied into each method.
295	     *
296	     * @param ownerId the id of the owner to load
297	     * @param action builds the response for an existing owner
298	     * @param <T> the response body type
299	     * @return the result of {@code action} for an existing owner, otherwise a 404 response
300	     */
301	    private <T> ResponseEntity<T> withOwner(Integer ownerId, Function<Owner, ResponseEntity<T>> action) {
302	        Owner owner = this.clinicService.findOwnerById(ownerId);
303	        if (owner == null) {
304	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
305	        }
306	        return action.apply(owner);
307	    }
308	
309	    /**
310	     * Maps a persisted owner to its {@link OwnerDto} and populates the read-only fields that are
311	     * derived from server-side state rather than stored columns (the {@code bulkSignupWarning} flag
312	     * and the {@code identityKey}). Both the create endpoint and the single-owner read endpoint
313	     * return their owner through this method, so an owner is decorated identically on either path
314	     * and each derived field is computed in exactly one place.
315	     *
316	     * @param owner the persisted owner to represent
317	     * @return the owner DTO with its derived read-only fields populated
318	     */
319	    private OwnerDto toOwnerDtoWithDerivedFields(Owner owner) {
320	        owner.setHouseholdSize(householdSize(owner));
321	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
322	        ownerDto.setBulkSignupWarning(bulkSignupWarning(owner.getRegistrationDate()));
323	        ownerDto.setIdentityKey(identityKey(owner));
324	        Integer possibleDuplicateOf = owner.getPossibleDuplicateOf();
325	        ownerDto.setPossibleDuplicate(possibleDuplicateOf != null);
326	        ownerDto.setPossibleDuplicateOf(possibleDuplicateOf);
327	        return ownerDto;
328	    }
329	
330	    /**
331	     * Canonicalizes the submitted address in place before it is validated, stored and returned, so
332	     * every later step - the required-field check, the persisted value and the response - sees the
333	     * single normalized form produced by {@link AddressNormalizer#normalize(String)} (see that method
334	     * for the trim/collapse/upper-case/abbreviation rules). Normalizing once here, at the head of the
335	     * create flow, keeps address canonicalization in exactly one place rather than spread across the
336	     * steps that read the address.
337	     *
338	     * <p>An address may be supplied either as the structured {@code addressLine1} (with an optional
339	     * {@code addressLine2}) or as the single flat {@code address}, the latter kept for backward
340	     * compatibility. Whichever address fields are supplied are normalized, and the structured fields
341	     * are preferred when present: the flat {@code address} returned is composed as the normalized
342	     * {@code addressLine1}, with a single space and the normalized {@code addressLine2} appended when an
343	     * {@code addressLine2} is present; only when no {@code addressLine1} is supplied does the flat
344	     * {@code address} retain its own normalized value.
345	     *
346	     * @param ownerFieldsDto the submitted owner fields, whose address fields are replaced with their normalized form
347	     */
348	    private void normalizeAddress(OwnerFieldsDto ownerFieldsDto) {
349	        String addressLine1 = addressNormalizer.normalize(ownerFieldsDto.getAddressLine1());
350	        String addressLine2 = addressNormalizer.normalize(ownerFieldsDto.getAddressLine2());
351	        String flatAddress = addressNormalizer.normalize(ownerFieldsDto.getAddress());
352	        ownerFieldsDto.setAddressLine1(addressLine1);
353	        ownerFieldsDto.setAddressLine2(addressLine2);
354	        if (addressLine1 != null && !addressLine1.isBlank()) {
355	            String composed = addressLine2 != null && !addressLine2.isBlank()
356	                ? addressLine1 + " " + addressLine2
357	                : addressLine1;
358	            ownerFieldsDto.setAddress(composed);
359	        } else {
360	            ownerFieldsDto.setAddress(flatAddress);
361	        }
362	    }
