364	    /**
365	     * Rejects an owner whose required text fields are blank (whitespace-only). Missing (null)
366	     * and empty fields are already rejected by Bean Validation on {@link OwnerFieldsDto}; this
367	     * closes the gap for {@code address} and {@code city}, whose values may be non-empty yet
368	     * blank (e.g. {@code "   "}). The offending field names are reported through an
369	     * {@link InvalidOwnerFieldsException}, which the {@code ExceptionControllerAdvice} renders
370	     * as a 400 response carrying an {@code errors} array of field names.
371	     *
372	     * @param ownerFieldsDto the submitted owner fields
373	     * @throws InvalidOwnerFieldsException if one or more required fields are blank
374	     */
375	    private void rejectBlankOwnerFields(OwnerFieldsDto ownerFieldsDto) {
376	        List<String> blankFields = new ArrayList<>();
377	        addIfBlank(blankFields, "firstName", ownerFieldsDto.getFirstName());
378	        addIfBlank(blankFields, "lastName", ownerFieldsDto.getLastName());
379	        addRequiredAddress(blankFields, ownerFieldsDto);
380	        addIfBlank(blankFields, "city", ownerFieldsDto.getCity());
381	        addIfBlank(blankFields, "telephone", ownerFieldsDto.getTelephone());
382	        if (!blankFields.isEmpty()) {
