458	    /**
459	     * Number of leading hex characters of the identity hash retained as the {@code HASH8} segment of
460	     * the {@code customerCode}.
461	     */
462	    private static final int CUSTOMER_CODE_HASH_LENGTH = 8;
463	
464	    /**
465	     * Builds the {@code customerCode} assigned to a newly created owner, formatted
466	     * {@code '<REGION>-<HASH8>'}: {@code REGION} is the owner's canonical region code resolved from
467	     * its {@code postcode} (falling back to its {@code city}) through the shared
468	     * {@link Region#code(String, String)}, and {@code HASH8} is the first 8 upper-case hex characters
469	     * of the SHA-256 digest of the owner's normalized telephone followed by its last name
470	     * (e.g. {@code 'NSW-1A2B3C4D'}). When this base code collides with an existing owner's
471	     * {@code customerCode}, {@code '-<n>'} is appended with the smallest {@code n} of 2 or more that
472	     * makes the result unique (e.g. {@code 'NSW-1A2B3C4D-2'}), so distinct owners always receive
473	     * distinct customer codes.
474	     *
475	     * @param owner the owner being created, with its telephone already normalized
476	     * @return the formatted, de-duplicated customer code
477	     */
478	    private String customerCode(Owner owner) {
479	        String region = Region.code(owner.getPostcode(), owner.getCity());
480	        String hash8 = hashPrefix(owner.getTelephone() + owner.getLastName(), CUSTOMER_CODE_HASH_LENGTH);
481	        String base = region + "-" + hash8;
482	        return deduplicateCustomerCode(base);
483	    }
484	
485	    /**
486	     * Ensures the given base {@code customerCode} does not collide with an existing owner's
487	     * {@code customerCode}. When no existing owner carries the base code it is returned unchanged;
488	     * otherwise {@code '-<n>'} is appended with the smallest {@code n} of 2 or more that yields a code
489	     * held by no existing owner.
490	     *
491	     * @param base the computed base customer code, formatted {@code '<REGION>-<HASH8>'}
492	     * @return the base code, or a {@code '<base>-<n>'} variant that is unique among existing owners
493	     */
494	    private String deduplicateCustomerCode(String base) {
495	        java.util.Set<String> existing = this.clinicService.findAllOwners().stream()
496	            .map(Owner::getCustomerCode)
497	            .filter(java.util.Objects::nonNull)
498	            .collect(java.util.stream.Collectors.toSet());
499	        if (!existing.contains(base)) {
500	            return base;
501	        }
502	        int n = 2;
503	        while (existing.contains(base + "-" + n)) {
504	            n++;
505	        }
506	        return base + "-" + n;
507	    }
