602	    /**
603	     * The fixed list of public holidays that are not business days. A registration date that lands
604	     * on one of these is rolled forward by {@link #businessDay(LocalDate)} to the next non-holiday
605	     * business day, exactly as it is rolled forward off a weekend.
606	     */
607	    private static final Set<LocalDate> PUBLIC_HOLIDAYS = Set.of(
608	        LocalDate.of(2026, 1, 1),
609	        LocalDate.of(2026, 1, 26),
610	        LocalDate.of(2026, 4, 25),
611	        LocalDate.of(2026, 12, 25),
612	        LocalDate.of(2026, 12, 28));
