614	    /**
615	     * Adjusts a date so it falls on a business day, rolling forward off weekends and public
616	     * holidays. A Saturday, Sunday or {@link #PUBLIC_HOLIDAYS listed public holiday} is rolled
617	     * forward one day at a time until the first non-holiday weekday is reached; any other weekday is
618	     * returned unchanged. Applied to the effective registration date so that a weekend or holiday
619	     * value - whether supplied in the request or defaulted to the server date - is stored as the
620	     * next business day, and every value derived from the registration date (such as the membership
621	     * number's year segment and the daily create-limit bucket) uses the adjusted business day.
622	     *
623	     * @param date the effective registration date
624	     * @return the same date when it is a non-holiday weekday, otherwise the next business day
625	     */
626	    private LocalDate businessDay(LocalDate date) {
627	        while (isNonBusinessDay(date)) {
628	            date = date.plusDays(1);
629	        }
630	        return date;
631	    }
