633	    /**
634	     * Whether the given date is a weekend day or a listed public holiday, and so not a business day.
635	     *
636	     * @param date the date to test
637	     * @return {@code true} for a Saturday, Sunday or {@link #PUBLIC_HOLIDAYS listed public holiday}
638	     */
639	    private boolean isNonBusinessDay(LocalDate date) {
640	        DayOfWeek dayOfWeek = date.getDayOfWeek();
641	        return dayOfWeek == DayOfWeek.SATURDAY
642	            || dayOfWeek == DayOfWeek.SUNDAY
643	            || PUBLIC_HOLIDAYS.contains(date);
644	    }
