708	     * @param owner the fully-populated owner being created (telephone, email and household id set)
709	     * @throws DuplicateOwnerIdentityException if an existing owner has the same identity key
710	     */
711	    private void rejectDuplicateIdentity(Owner owner) {
712	        String key = identityKey(owner);
713	        boolean duplicate = existingOwnerMatches(this::identityKey, key);
714	        if (duplicate) {
715	            throw new DuplicateOwnerIdentityException(key);
