729	     * @param owner the fully-populated owner being created (household id set)
730	     * @param sharesHousehold whether the request declared it shares an existing household
731	     * @throws DuplicateOwnerIdentityException if the household already exists and was not declared
732	     */
733	    private void rejectHouseholdDuplicate(Owner owner, boolean sharesHousehold) {
734	        if (sharesHousehold) {
735	            return;
736	        }
737	        String household = owner.getHouseholdId();
738	        if (household == null) {
739	            return;
740	        }
741	        if (existingOwnerMatches(this::householdId, household)) {
742	            throw new DuplicateOwnerIdentityException(identityKey(owner));
