746	    /**
747	     * Computes the soft-match {@code possibleDuplicateOf} for a newly created owner: the id of the
748	     * first existing owner that shares this owner's {@code lastName} (compared case-insensitively) and
749	     * {@code postcode} while carrying a <em>different</em> telephone (compared by canonical E.164 form,
750	     * see {@link TelephoneNormalizer#canonicalize(String)}), or {@code null} when no such owner exists.
751	     * The check runs only after the exact-identity duplicate check ({@link #rejectDuplicateIdentity(Owner)})
752	     * has passed, so a shared last-name-and-postcode with the same telephone has already been rejected as
753	     * a hard duplicate and can never surface here. A blank {@code postcode} never matches, since two
754	     * owners without a postcode do not share one. The captured id is stored on the new owner and surfaced
755	     * as the read-only {@code possibleDuplicate} / {@code possibleDuplicateOf} fields.
756	     *
757	     * @param owner the fully-populated owner being created (telephone normalized)
758	     * @return the id of the first soft-matching existing owner, or {@code null} when none matches
759	     */
760	    private Integer possibleDuplicateOf(Owner owner) {
761	        if (owner.getPostcode() == null || owner.getPostcode().isBlank()) {
762	            return null;
763	        }
764	        String telephone = telephoneNormalizer.canonicalize(owner.getTelephone());
765	        return this.clinicService.findAllOwners().stream()
766	            .filter(existing -> equalsIgnoreCase(existing.getLastName(), owner.getLastName())
767	                && owner.getPostcode().equals(existing.getPostcode())
768	                && !java.util.Objects.equals(telephone, telephoneNormalizer.canonicalize(existing.getTelephone())))
769	            .map(Owner::getId)
770	            .filter(java.util.Objects::nonNull)
771	            .findFirst()
772	            .orElse(null);
773	    }
