775	    /**
776	     * Reduces an owner to its derived {@code identityKey}, formatted
777	     * {@code '<normalizedTelephone>|<email>|<householdId>'}: the owner's telephone reduced to its
778	     * canonical E.164 form (see {@link TelephoneNormalizer#canonicalize(String)}), the owner's
779	     * normalized (lower-cased) email or the empty string when absent (see
780	     * {@link EmailNormalizer#normalize(String)}), and the owner's {@code householdId} or the empty
781	     * string when absent, joined by {@code '|'}. Two owners are duplicates exactly when their whole
782	     * identity keys are equal. The key never contains {@code null} segments, so the create endpoint's
783	     * single duplicate check compares this one value across owners.
784	     *
785	     * @param owner the owner to derive the identity key for
786	     * @return the owner's identity key
787	     */
788	    private String identityKey(Owner owner) {
789	        String telephone = telephoneNormalizer.canonicalize(owner.getTelephone());
790	        String normalizedEmail = emailNormalizer.normalize(owner.getEmail());
791	        String email = normalizedEmail == null ? "" : normalizedEmail;
792	        String household = owner.getHouseholdId() == null ? "" : owner.getHouseholdId();
793	        return telephone + "|" + email + "|" + household;
794	    }
