796	    /**
797	     * Finds the first existing owner that already carries the given comparison {@code key}, derived
798	     * from each owner by {@code keyExtractor}. Owners for which the extractor yields {@code null} are
799	     * ignored (a {@code null} key never equals the sought key). The create endpoint's duplicate
800	     * checks reduce both an existing owner and the owner being created to the same canonical key;
801	     * this returns the matched existing owner itself, so a caller can either reject the collision or
802	     * record which owner was matched. Owners flagged deleted (soft-deleted) are excluded, so a
803	     * collision with only a deleted owner is not reported and the create is allowed.
804	     *
805	     * @param keyExtractor derives an owner's canonical comparison key (may return {@code null})
806	     * @param key the canonical key of the owner being created
807	     * @return the first existing owner sharing the key, or empty when none does
808	     */
809	    private Optional<Owner> findExistingOwner(Function<Owner, String> keyExtractor, String key) {
810	        return this.clinicService.findAllOwners().stream()
811	            .filter(owner -> !owner.isDeleted())
812	            .filter(owner -> key.equals(keyExtractor.apply(owner)))
813	            .findFirst();
814	    }
