822	     * @param keyExtractor derives an owner's canonical comparison key (may return {@code null})
823	     * @param key the canonical key of the owner being created
824	     * @return {@code true} if some existing owner shares the key
825	     */
826	    private boolean existingOwnerMatches(Function<Owner, String> keyExtractor, String key) {
827	        return findExistingOwner(keyExtractor, key).isPresent();
828	    }
