830	    /**
831	     * Counts the existing owners that satisfy the given {@code predicate}. The create endpoint's
832	     * count-based rules - the per-city capacity, the per-day create limit and the derived
833	     * {@code namesakeCount} - all accumulate owners over {@link ClinicService#findAllOwners()} and
834	     * differ only in the predicate they count by, so the scan-and-count is written in exactly one
835	     * place and each rule supplies just its own predicate.
836	     *
837	     * @param predicate the condition an owner must satisfy to be counted
838	     * @return the number of existing owners that satisfy the predicate
839	     */
840	    private long countOwners(Predicate<Owner> predicate) {
841	        return this.clinicService.findAllOwners().stream()
842	            .filter(predicate)
843	            .count();
844	    }
845	
846	    /**
847	     * Delimiter joining the canonical {@code lastName} and the {@code postcode} when deriving the
848	     * shared {@code householdId}.
849	     */
850	    private static final String HOUSEHOLD_KEY_DELIMITER = "|";
851	
852	    /**
853	     * Reduces the household {@code lastName} to a canonical form for case-insensitive,
854	     * whitespace-insensitive comparison: leading and trailing whitespace is trimmed, every run of
855	     * internal whitespace is collapsed to a single space, and the result is lower-cased using
856	     * {@link java.util.Locale#ROOT} so comparison is locale-independent.
857	     *
858	     * @param value the raw field value, or {@code null}
859	     * @return the canonical value, or {@code null} when {@code value} is {@code null}
860	     */
861	    private String canonicalizeHousehold(String value) {
862	        return value == null ? null : value.trim().replaceAll("\\s+", " ").toLowerCase(java.util.Locale.ROOT);
863	    }
864	
865	    /**
866	     * Derives the deterministic, shared {@code householdId} for an owner from its {@code lastName}
867	     * and {@code postcode}. The identifier is the first 12 upper-case hex characters of the SHA-256
868	     * hash of {@code normalizedLastName + '|' + postcode} (see {@link #canonicalizeHousehold(String)}
869	     * for the last-name normalization), so every owner with the same last name and postcode -
870	     * regardless of casing or spacing - is automatically assigned the identical value. Owners without
871	     * a postcode have no household basis and are given no household id ({@code null}).
872	     *
873	     * @param owner the owner being created
874	     * @return the shared household identifier, or {@code null} when the owner has no postcode
875	     */
876	    /**
877	     * Counts the owners in the given owner's household: the existing owners that share its
878	     * {@code householdId} (see {@link #householdId(Owner)}), which - because the owner being counted is
879	     * itself persisted before it is decorated - includes the owner. An owner with no {@code householdId}
880	     * (e.g. no postcode) has no shared household and counts as a household of one. The value feeds the
881	     * household factor of the owner's membership points.
882	     *
883	     * @param owner the owner whose household size is being derived
884	     * @return the number of owners in the owner's household (at least {@code 1})
885	     */
886	    private int householdSize(Owner owner) {
887	        String household = owner.getHouseholdId();
888	        if (household == null) {
889	            return 1;
890	        }
891	        return (int) countOwners(existing -> household.equals(existing.getHouseholdId()));
892	    }
893	
894	    private String householdId(Owner owner) {
895	        String postcode = owner.getPostcode();
896	        if (postcode == null || postcode.isBlank()) {
897	            return null;
898	        }
899	        String key = canonicalizeHousehold(owner.getLastName()) + HOUSEHOLD_KEY_DELIMITER + postcode;
900	        return hashPrefix(key, HOUSEHOLD_ID_LENGTH);
901	    }
902	
903	    /**
904	     * Number of leading hex characters of the household hash retained as the shared
905	     * {@code householdId}.
906	     */
907	    private static final int HOUSEHOLD_ID_LENGTH = 12;
908	
909	    /**
910	     * Computes the leading {@code length} upper-case hex characters of the SHA-256 digest of the
911	     * UTF-8 bytes of {@code input}. This is the shared hashing primitive behind the derived
912	     * identifiers that fingerprint owner fields - such as the household-scoped {@code householdId} -
913	     * so every such identifier is produced by the same algorithm and differs only in the value it
914	     * hashes and the number of hex characters it keeps.
915	     *
916	     * @param input the value to hash
917	     * @param length the number of leading hex characters to keep
918	     * @return the leading {@code length} upper-case hex characters of the SHA-256 digest
919	     */
920	    private String hashPrefix(String input, int length) {
921	        try {
922	            byte[] digest = java.security.MessageDigest.getInstance("SHA-256")
923	                .digest(input.getBytes(java.nio.charset.StandardCharsets.UTF_8));
924	            StringBuilder sb = new StringBuilder(digest.length * 2);
925	            for (byte b : digest) {
926	                sb.append(String.format("%02X", b));
927	            }
928	            return sb.substring(0, length);
929	        } catch (java.security.NoSuchAlgorithmException e) {
930	            throw new IllegalStateException("SHA-256 is required but unavailable", e);
931	        }
932	    }
933	}
